
function labPhysicsReset(d){d.ball={x:60,y:45,vx:0,vy:0};d.running=false;d.age=0;d.star=false;}
LAB_ENGINES.physics={
 init(c,seed){const d={lines:[],ink:0,maxInk:650,goal:{x:470+seed%3*15,y:265},drawing:false};labPhysicsReset(d);return d;},
 render(d,c){return '<p>Draw ramps with your finger or mouse, then release the ball. '+(c.variant==='join'?'Bring the blue ball to its pink friend.':c.variant==='brain'?'Guide the ball into the glowing goal using at most 650 units of ink.':'Guide the ball into the cup.')+' You can undo and retry.</p><svg id="lab-physics" viewBox="0 0 600 300" class="lab-drawing"><defs><linearGradient id="lab-sky" x2="0" y2="1"><stop stop-color="#d9efff"/><stop offset="1" stop-color="#fff1d1"/></linearGradient></defs><rect width="600" height="300" fill="url(#lab-sky)"/><path d="M0 288 H600" stroke="#71869d" stroke-width="6"/>'+(c.variant==='join'?'<circle cx="'+d.goal.x+'" cy="'+d.goal.y+'" r="16" fill="#e672a8"/><text x="'+(d.goal.x-7)+'" y="'+(d.goal.y+5)+'" fill="white">♥</text>':'<path d="M'+(d.goal.x-25)+' 252 v34 h50 v-34" fill="#f3d788" stroke="#ad8330" stroke-width="5"/>')+'<g id="lab-ramps">'+d.lines.map(line=>'<polyline points="'+line.map(p=>p.x+','+p.y).join(' ')+'" stroke="#7a4fb0" stroke-width="5" fill="none" stroke-linecap="round"/>').join('')+'</g><circle id="lab-ball" cx="'+d.ball.x+'" cy="'+d.ball.y+'" r="10" fill="#359cce" stroke="white" stroke-width="3"/></svg><p id="lab-ink">Ink '+Math.round(d.ink)+' / '+d.maxInk+'</p>'+labButton('release','Release ball',0,d.running)+labButton('undo','Undo line',0,d.running)+labButton('resetball','Reset ball');},
 action(d,a){if(a==='release'){if(!d.lines.length){labMiss('Draw at least one ramp first.');return;}labPhysicsReset(d);d.running=true;}if(a==='resetball')labPhysicsReset(d);if(a==='undo'&&!d.running){d.lines.pop();d.ink=d.lines.reduce((sum,line)=>sum+line.slice(1).reduce((s,p,i)=>s+Math.hypot(p.x-line[i].x,p.y-line[i].y),0),0);}},
 bind(d){const svg=$('#lab-physics');if(!svg)return;const point=e=>{const matrix=svg.getScreenCTM(),p=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());return {x:Math.max(0,Math.min(600,p.x)),y:Math.max(15,Math.min(282,p.y))};};let pointer=null,line=null,element=null;svg.onpointerdown=e=>{if(d.running||pointer!==null||d.ink>=d.maxInk)return;e.preventDefault();pointer=e.pointerId;svg.setPointerCapture(pointer);line=[point(e)];d.lines.push(line);element=document.createElementNS('http://www.w3.org/2000/svg','polyline');element.setAttribute('stroke','#7a4fb0');element.setAttribute('stroke-width','5');element.setAttribute('fill','none');$('#lab-ramps').append(element);};svg.onpointermove=e=>{if(e.pointerId!==pointer||!line)return;const p=point(e),last=line.at(-1),length=Math.hypot(p.x-last.x,p.y-last.y);if(length<3||d.ink+length>d.maxInk)return;line.push(p);d.ink+=length;element.setAttribute('points',line.map(p=>p.x+','+p.y).join(' '));$('#lab-ink').textContent='Ink '+Math.round(d.ink)+' / '+d.maxInk;};const finish=e=>{if(e.pointerId!==pointer)return;pointer=null;line=null;game.session.moves++;};svg.onpointerup=finish;svg.onpointercancel=finish;},
 step(d,dt,c){if(!d.running)return;const ball=d.ball,steps=Math.max(1,Math.ceil(dt/.008)),h=dt/steps;for(let k=0;k<steps;k++){ball.vy+=160*h;ball.x+=ball.vx*h;ball.y+=ball.vy*h;for(const line of d.lines)for(let j=1;j<line.length;j++){const a=line[j-1],b=line[j],dx=b.x-a.x,dy=b.y-a.y,len=dx*dx+dy*dy;if(!len)continue;const t=Math.max(0,Math.min(1,((ball.x-a.x)*dx+(ball.y-a.y)*dy)/len)),x=a.x+t*dx,y=a.y+t*dy,dist=Math.hypot(ball.x-x,ball.y-y);if(dist<12){const nx=dist?(ball.x-x)/dist:0,ny=dist?(ball.y-y)/dist:-1,dot=ball.vx*nx+ball.vy*ny;ball.x=x+nx*12;ball.y=y+ny*12;if(dot<0){ball.vx-=dot*nx;ball.vy-=dot*ny;ball.vx*=.999;ball.vy*=.999;}}}if(ball.y>276){ball.y=276;ball.vy=0;ball.vx*=.995;}if(ball.x<10){ball.x=10;ball.vx=Math.abs(ball.vx)*.3;}if(ball.x>590){ball.x=590;ball.vx=-Math.abs(ball.vx)*.3;}if(Math.abs(ball.x-d.goal.x)<22&&ball.y>247){d.running=false;labWin(c.variant==='join'?'The two friends are together!':'The ball reached the cup!');renderGame();return;}}d.age+=dt;const el=$('#lab-ball');if(el){el.setAttribute('cx',ball.x);el.setAttribute('cy',ball.y);}if(d.age>18){d.running=false;game.session.message='The ball stopped short. Adjust your ramps and retry.';renderGame();}}
};
